/**
 * Expo config plugin: wires up real release signing on Android.
 *
 * `mobile/android/` is gitignored and gets fully regenerated by
 * `expo prebuild` (see build_bundle_android_release.bat), so any manual
 * edit to android/app/build.gradle is lost the next time prebuild runs.
 * This plugin re-applies the release signing config on every prebuild:
 *
 *   1. Copies mobile/release.keystore into android/app/release.keystore
 *   2. Injects the signing credentials into android/gradle.properties
 *      (read from mobile/release.properties, which is gitignored and
 *      must never be committed)
 *   3. Rewrites the `release` buildType's signingConfig to use a real
 *      `signingConfigs.release` block instead of signingConfigs.debug
 *
 * If mobile/release.properties or mobile/release.keystore is missing,
 * the plugin leaves build.gradle untouched (falls back to debug signing)
 * and prints a warning — this keeps `expo prebuild` usable on machines
 * that don't have the release credentials (e.g. CI, other contributors).
 */
const fs = require('fs');
const path = require('path');
const {
  withGradleProperties,
  withAppBuildGradle,
  withDangerousMod,
} = require('@expo/config-plugins');

function loadReleaseProperties(projectRoot) {
  const propsPath = path.join(projectRoot, 'release.properties');
  if (!fs.existsSync(propsPath)) return null;

  const props = {};
  for (const line of fs.readFileSync(propsPath, 'utf8').split('\n')) {
    const trimmed = line.trim();
    if (!trimmed || trimmed.startsWith('#')) continue;
    const idx = trimmed.indexOf('=');
    if (idx === -1) continue;
    props[trimmed.slice(0, idx).trim()] = trimmed.slice(idx + 1).trim();
  }

  const required = [
    'RELEASE_STORE_FILE',
    'RELEASE_KEY_ALIAS',
    'RELEASE_STORE_PASSWORD',
    'RELEASE_KEY_PASSWORD',
  ];
  for (const key of required) {
    if (!props[key]) return null;
  }
  return props;
}

const withReleaseSigning = (config) => {
  config = withDangerousMod(config, [
    'android',
    (config) => {
      const props = loadReleaseProperties(config.modRequest.projectRoot);
      if (!props) {
        console.warn(
          '[withReleaseSigning] mobile/release.properties not found or incomplete — ' +
            'release build will fall back to debug signing. See mobile/plugins/withReleaseSigning.js.'
        );
        return config;
      }
      const src = path.join(config.modRequest.projectRoot, props.RELEASE_STORE_FILE);
      const dest = path.join(
        config.modRequest.platformProjectRoot,
        'app',
        'release.keystore'
      );
      if (!fs.existsSync(src)) {
        console.warn(`[withReleaseSigning] keystore not found at ${src} — skipping.`);
        return config;
      }
      fs.copyFileSync(src, dest);
      return config;
    },
  ]);

  config = withGradleProperties(config, (config) => {
    const props = loadReleaseProperties(config.modRequest.projectRoot);
    if (!props) return config;

    const keys = {
      MYAPP_RELEASE_STORE_FILE: 'release.keystore',
      MYAPP_RELEASE_KEY_ALIAS: props.RELEASE_KEY_ALIAS,
      MYAPP_RELEASE_STORE_PASSWORD: props.RELEASE_STORE_PASSWORD,
      MYAPP_RELEASE_KEY_PASSWORD: props.RELEASE_KEY_PASSWORD,
    };
    for (const [key, value] of Object.entries(keys)) {
      config.modResults = config.modResults.filter((item) => item.key !== key);
      config.modResults.push({ type: 'property', key, value });
    }
    return config;
  });

  config = withAppBuildGradle(config, (config) => {
    const props = loadReleaseProperties(config.modRequest.projectRoot);
    if (!props) return config;

    let contents = config.modResults.contents;

    if (!contents.includes('MYAPP_RELEASE_STORE_FILE')) {
      contents = contents.replace(
        /signingConfigs\s*\{/,
        `signingConfigs {
        release {
            storeFile file(MYAPP_RELEASE_STORE_FILE)
            storePassword MYAPP_RELEASE_STORE_PASSWORD
            keyAlias MYAPP_RELEASE_KEY_ALIAS
            keyPassword MYAPP_RELEASE_KEY_PASSWORD
        }`
      );
    }

    contents = contents.replace(
      /(release\s*\{[^}]*?signingConfig\s+signingConfigs\.)debug/,
      '$1release'
    );

    config.modResults.contents = contents;
    return config;
  });

  return config;
};

module.exports = withReleaseSigning;
